// "Who hits whom": victims (rows) × opposing party (columns). Bubble area = people hurt, colour = share severe.
import { h, s, fmt, pct, tooltip, showTip, hideTip } from '../util.js';
import { ramp } from '../theme.js';
import { MODE_ICON, OPP_ICON, iconBody, icon } from '../icons.js';
import { NMODE, NOPP, cellOf } from '../engine.js';

const CW = 28, CH = 34, LW = 114, GAP = 9, HEAD = 56, TOP = 14;
const SHORT = ['Ped.', 'Bike', 'E-sc.', 'Moto', 'Car', 'Van', 'Truck', 'Other', 'Animal', 'Obstacle', 'Alone'];
const ROWNAME = ['Pedestrian', 'Bicycle', 'E-scooter', 'Moped / moto', 'Car', 'Van', 'Heavy vehicle', 'Other vehicle'];
const W = LW + NOPP * CW + GAP + 4, H = TOP + HEAD + NMODE * CH + 4;
const cx = (j) => LW + j * CW + (j >= 8 ? GAP : 0) + CW / 2;
const cy = (i) => TOP + HEAD + i * CH + CH / 2;

export const pairName = (meta, c) => {
  const m = Math.floor(c / NOPP), o = c % NOPP;
  return { victim: ROWNAME[m], opp: meta.opps[o].label };
};

export function Matrix({ engine, meta, theme, onChange }) {
  const svg = s('svg.mx', { viewBox: `0 0 ${W} ${H}`, role: 'group', 'aria-label': 'Collision matrix: victim mode by opposing party' });
  let metric = 'victims';

  // ---- static skeleton ---------------------------------------------------------------------
  svg.append(s('text.axis', { x: LW, y: 9 }, 'OPPOSING PARTY'), s('text.axis', { x: 0, y: TOP + HEAD - 6 }, 'VICTIM'));
  svg.append(s('text.axis.grp', { x: cx(8) - CW / 2, y: 9 }, 'NO OTHER VEHICLE'));
  const colHeads = [], rowHeads = [], cells = [], guides = [];
  for (let j = 0; j < NOPP; j++) {
    const g = s('g.colhead', { tabindex: 0, role: 'button', 'aria-label': `Select every victim facing: ${meta.opps[j].label}` },
      s('rect', { x: cx(j) - CW / 2, y: TOP, width: CW, height: HEAD - 4, rx: 6 }),
      s('svg', { x: cx(j) - 9, y: TOP + 6, width: 18, height: 18, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': 1.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', html: iconBody(OPP_ICON[j]) }),
      s('text.cl', { x: cx(j), y: TOP + 38, 'text-anchor': 'middle' }, SHORT[j]));
    g.addEventListener('click', () => selectLine('col', j));
    g.addEventListener('keydown', (e) => (e.key === 'Enter' || e.key === ' ') && (e.preventDefault(), selectLine('col', j)));
    tooltip(g, () => `<div class="tt-h">${meta.opps[j].label}</div><div class="tt-r tt-dim">Click to select every victim type facing this opponent</div>`);
    svg.append(g); colHeads.push(g);
  }
  for (let i = 0; i < NMODE; i++) {
    const band = s('rect.band', { x: 0, y: cy(i) - CH / 2, width: W, height: CH, rx: 6 });
    guides.push(band); svg.append(band);
  }
  for (let i = 0; i < NMODE; i++) {
    const nameT = s('text.rn', { x: 24, y: cy(i) - 2 }, ROWNAME[i]), cntT = s('text.rc', { x: 24, y: cy(i) + 10 }, '');
    const g = s('g.rowhead', { tabindex: 0, role: 'button', 'aria-label': `Select all ${ROWNAME[i]} victims` },
      s('rect', { x: 0, y: cy(i) - CH / 2 + 1, width: LW - 4, height: CH - 2, rx: 6 }),
      s('circle.mdot', { cx: 8, cy: cy(i), r: 3, fill: theme.mode[i] }),
      s('svg', { x: 12, y: cy(i) - 6, width: 0, height: 0 }), nameT, cntT);
    g.querySelector('svg')?.remove();
    g.append(s('svg', { x: LW - 24, y: cy(i) - 8, width: 16, height: 16, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': 1.6, 'stroke-linecap': 'round', 'stroke-linejoin': 'round', class: 'ri', html: iconBody(MODE_ICON[i]) }));
    g.addEventListener('click', () => selectLine('row', i));
    g.addEventListener('keydown', (e) => (e.key === 'Enter' || e.key === ' ') && (e.preventDefault(), selectLine('row', i)));
    tooltip(g, () => `<div class="tt-h">${ROWNAME[i]}</div><div class="tt-r tt-dim">Click to select this victim type against every opponent</div>`);
    svg.append(g); rowHeads.push({ g, cntT });
  }
  for (let i = 0; i < NMODE; i++) {
    for (let j = 0; j < NOPP; j++) {
      const c = cellOf(i, j);
      const circle = s('circle.bub', { cx: cx(j), cy: cy(i), r: 0 });
      const ring = s('circle.sel', { cx: cx(j), cy: cy(i), r: 0 });
      const hit = s('rect.hit', { x: cx(j) - CW / 2 + 1, y: cy(i) - CH / 2 + 1, width: CW - 2, height: CH - 2, rx: 5 });
      const g = s('g.cell', { tabindex: 0, role: 'button', 'aria-pressed': 'false', 'data-c': c }, hit, circle, ring);
      g.addEventListener('click', () => { engine.togglePair(c); onChange(); });
      g.addEventListener('keydown', (e) => (e.key === 'Enter' || e.key === ' ') && (e.preventDefault(), engine.togglePair(c), onChange()));
      g.addEventListener('pointerenter', () => hover(i, j)); g.addEventListener('pointerleave', () => hover(null, null));
      tooltip(g, () => cellTip(i, j));
      svg.append(g); cells.push({ g, circle, ring, c, i, j });
    }
  }
  const cellsLayer = cells; // alias for clarity

  function selectLine(kind, k) {
    const set = []; for (let i = 0; i < NMODE; i++) for (let j = 0; j < NOPP; j++) if ((kind === 'row' ? i : j) === k) set.push(cellOf(i, j));
    const all = set.every((c) => engine.pairMask[c]);
    for (const c of set) if (!!engine.pairMask[c] === all) engine.togglePair(c);
    onChange();
  }
  function hover(i, j) {
    guides.forEach((b, k) => b.classList.toggle('on', k === i));
    cells.forEach((c) => c.g.classList.toggle('xhair', i != null && (c.i === i || c.j === j)));
    colHeads.forEach((g, k) => g.classList.toggle('on', k === j));
    rowHeads.forEach((r, k) => r.g.classList.toggle('on', k === i));
    caption(i, j);
  }

  // ---- numbers ---------------------------------------------------------------------------------
  let vals = null;
  const stats = (R, i, j) => {
    const c = cellOf(i, j), n = R.cell.n[c], sv = R.cell.sev;
    return { n, slight: sv[c * 4 + 1], hosp: sv[c * 4 + 2], killed: sv[c * 4 + 3] };
  };
  function cellTip(i, j) {
    const R = engine.R, st = stats(R, i, j), name = pairName(meta, cellOf(i, j));
    const sel = engine.pairMask[cellOf(i, j)];
    if (!st.n) return `<div class="tt-h">${name.victim} × ${name.opp}</div><div class="tt-r tt-dim">No victims with the current filters</div>`;
    return `<div class="tt-h">${name.victim} × ${name.opp}</div>` +
      `<div class="tt-r"><b>${fmt(st.n)}</b> people hurt or killed</div>` +
      `<div class="tt-r"><i class="sw" style="background:${theme.sev[3]}"></i>${fmt(st.killed)} killed (${pct(st.killed / st.n)})</div>` +
      `<div class="tt-r"><i class="sw" style="background:${theme.sev[2]}"></i>${fmt(st.hosp)} hospitalised (${pct(st.hosp / st.n)})</div>` +
      `<div class="tt-r"><i class="sw" style="background:${theme.sev[1]}"></i>${fmt(st.slight)} slightly injured</div>` +
      `<div class="tt-r tt-dim">${sel ? 'Click to remove from selection' : 'Click to filter the map and every chart'}</div>`;
  }

  const caption = (i, j) => {
    const el = capEl;
    if (i == null) { el.innerHTML = defaultCaption; return; }
    const st = stats(engine.R, i, j), name = pairName(meta, cellOf(i, j));
    el.innerHTML = st.n
      ? `<b>${name.victim}</b> × <b>${name.opp}</b> — ${fmt(st.n)} people hurt, <span class="k">${fmt(st.killed)} killed</span> (${pct(st.killed / st.n)}), ${pct((st.killed + st.hosp) / st.n, 0)} severe`
      : `<b>${name.victim}</b> × <b>${name.opp}</b> — none with the current filters`;
  };

  const capEl = h('p.mx-cap');
  let defaultCaption = '';

  // ---- table view ------------------------------------------------------------------------------
  const tableEl = h('div.mx-table', { hidden: true });
  const rendered = (R) => {
    const m = metric === 'killed';
    let vmax = 1;
    const rowTot = new Array(NMODE).fill(0);
    for (let i = 0; i < NMODE; i++) for (let j = 0; j < NOPP; j++) {
      const st = stats(R, i, j), v = m ? st.killed : st.n;
      vmax = Math.max(vmax, v); rowTot[i] += st.n;
    }
    const any = engine.pairCount > 0;
    for (const c of cellsLayer) {
      const st = stats(R, c.i, c.j), v = m ? st.killed : st.n, sh = st.n ? (m ? st.killed / st.n : (st.killed + st.hosp) / st.n) : 0;
      const r = v ? Math.max(1.6, Math.sqrt(v / vmax) * (CW / 2 - 1.5)) : 0;
      c.circle.style.r = r + 'px';
      c.circle.style.fill = v ? ramp(sh / (m ? 0.14 : 0.6)) : 'transparent';
      const on = !!engine.pairMask[c.c];
      c.ring.style.r = on ? r + 2.4 + 'px' : '0px';
      c.g.classList.toggle('on', on); c.g.classList.toggle('dim', any && !on); c.g.classList.toggle('empty', !st.n);
      c.g.setAttribute('aria-pressed', on);
      c.g.setAttribute('aria-label', `${pairName(meta, c.c).victim} × ${pairName(meta, c.c).opp}: ${fmt(st.n)} victims, ${fmt(st.killed)} killed`);
    }
    rowHeads.forEach((r, i) => { r.cntT.textContent = rowTot[i] ? `${fmt(rowTot[i])} hurt` : '—'; r.g.classList.toggle('zero', !rowTot[i]); });
    vals = { rowTot };
    // insight line
    let big = null, lethal = null;
    const minN = Math.max(30, R.victims * 0.0006);
    for (let i = 0; i < NMODE; i++) for (let j = 0; j < NOPP; j++) {
      const st = stats(R, i, j);
      if (!big || st.n > big.st.n) big = { i, j, st };
      if (st.n >= minN && (!lethal || st.killed / st.n > lethal.st.killed / lethal.st.n)) lethal = { i, j, st };
    }
    const nm = (o) => pairName(meta, cellOf(o.i, o.j));
    defaultCaption = big && big.st.n
      ? `Most frequent: <b>${nm(big).victim} × ${nm(big).opp}</b> (${fmt(big.st.n)}).` + (lethal ? ` Deadliest with ≥${fmt(minN)} victims: <b>${nm(lethal).victim} × ${nm(lethal).opp}</b>, <span class="k">${pct(lethal.st.killed / lethal.st.n)} killed</span>.` : '')
      : 'No accidents match the current filters.';
    if (!capEl.dataset.hover) capEl.innerHTML = defaultCaption;
    if (!tableEl.hidden) buildTable(R);
  };

  function buildTable(R) {
    const m = metric === 'killed';
    tableEl.replaceChildren(h('table', { 'aria-label': 'Collision matrix as a table' },
      h('thead', h('tr', h('th', 'Victim ↓ / Opponent →'), meta.opps.map((o) => h('th', { title: o.label }, SHORT[o.id === undefined ? 0 : meta.opps.indexOf(o)])))),
      h('tbody', ROWNAME.map((r, i) => h('tr', h('th', r), Array.from({ length: NOPP }, (_, j) => {
        const st = stats(R, i, j), c = cellOf(i, j);
        return h('td', { class: engine.pairMask[c] ? 'on' : '', onclick: () => { engine.togglePair(c); onChange(); }, title: `${fmt(st.n)} hurt · ${fmt(st.killed)} killed` }, st.n ? fmt(m ? st.killed : st.n) : '·');
