    ...[['victims', 'People hurt'], ['killed', 'Killed']].map(([v, l]) => h('button', { type: 'button', role: 'radio', 'aria-checked': v === metric, 'data-v': v, onclick: (e) => { metric = v; seg.querySelectorAll('button').forEach((b) => b.setAttribute('aria-checked', b.dataset.v === v)); rendered(engine.R); } }, l)));
  const tableBtn = h('button.icon-btn', { type: 'button', title: 'Show as table', 'aria-label': 'Toggle table view', html: icon('table', 16), onclick: () => { tableEl.hidden = !tableEl.hidden; svg.parentElement.classList.toggle('as-table', !tableEl.hidden); if (!tableEl.hidden) buildTable(engine.R); } });
  const clearBtn = h('button.link', { type: 'button', hidden: true, onclick: () => { engine.setPairs([]); onChange(); } }, 'Clear selection');

  const legend = h('div.mx-legend',
    h('span', 'Area = ', h('b', { class: 'mxl' }, 'people hurt')),
    h('span.mx-l2', h('span', 'Colour = share killed or hospitalised'), h('span.rl-scale', { style: { background: `linear-gradient(90deg, ${ramp(0)}, ${ramp(0.5)}, ${ramp(1)})` } }), h('span', '0 → 60%')));
  const el = h('section.card.matrix',
    h('header.card-h', h('div', h('p.eyebrow', 'Who hits whom'), h('h2', 'Collision matrix')), h('span.grow'), seg, tableBtn),
    h('p.lede', 'Each bubble counts people injured or killed, by their mode of transport and what they collided with. ', h('b', 'Click cells'), ' to filter the map and every chart.'),
    h('div.mx-wrap', svg, tableEl), capEl, h('div.mx-foot', legend, clearBtn));
  svg.addEventListener('pointerleave', () => { delete capEl.dataset.hover; capEl.innerHTML = defaultCaption; });
  svg.addEventListener('pointermove', () => { capEl.dataset.hover = '1'; });

  return {
    el,
    update(R) { rendered(R); clearBtn.hidden = !engine.pairCount; },
  };
}
